function translate(text) {
  const key = text.trim().replace(/\s+/g, ' ');
  const direct = korean.get(key);
  if (direct) return text.replace(/\S[\s\S]*\S|\S/, direct);
  const patterns = [
    [/^Practice (\d+)$/, '연습 $1'],
    [/^(\d+ \/ \d+) landmarks$/, '관절 $1'],
    [/^Hands: (\d+)$/, '손 $1개 감지'],
    [/^([\d.]+) seconds$/, '$1초'],
  ];
  for (const [pattern, replacement] of patterns) {
    if (pattern.test(key)) return key.replace(pattern, replacement);
  }
  const pageTitle = key.match(/^(.+) · AirNav$/);
  if (pageTitle && korean.has(pageTitle[1])) return korean.get(pageTitle[1]) + ' · AirNav';
  return text;
}

const originals = new WeakMap();
const attributes = ['aria-label', 'alt', 'title'];
let language = 'en';
try { if (localStorage.getItem('airnav-language') === 'ko') language = 'ko'; } catch {}

function update(node, key, current, write) {
  let fields = originals.get(node);
  if (!fields) originals.set(node, fields = new Map());
  const previous = fields.get(key);
  const source = previous?.output === current ? previous.source : current;
  const output = language === 'ko' ? translate(source) : source;
  if (output !== source || previous) fields.set(key, { source, output });
  if (output !== current) write(output);
}

function visit(node) {
  if (node.nodeType === Node.TEXT_NODE) {
    if (node.parentElement?.closest('script, style, [data-language]')) return;
    if (node.data.trim()) update(node, 'text', node.data, value => { node.data = value; });
  } else if (node.nodeType === Node.ELEMENT_NODE) {
    for (const name of attributes) {
      if (node.hasAttribute(name)) update(node, name, node.getAttribute(name), value => node.setAttribute(name, value));
    }
    node.childNodes.forEach(visit);
  }
}

const buttons = [...document.querySelectorAll('[data-language]')];
function applyLanguage() {
  document.documentElement.lang = language;
  buttons.forEach(button => button.setAttribute('aria-pressed', String(button.dataset.language === language)));
  visit(document.body);
  visit(document.querySelector('title'));
}

buttons.forEach(button => button.addEventListener('click', () => {
  language = button.dataset.language;
  try { localStorage.setItem('airnav-language', language); } catch {}
  applyLanguage();
}));
applyLanguage();
const observer = new MutationObserver(records => {
  for (const record of records) {
    if (record.type === 'characterData') visit(record.target);
    else if (record.type === 'attributes') {
      const node = record.target;
      const name = record.attributeName;
      if (node.hasAttribute(name)) update(node, name, node.getAttribute(name), value => node.setAttribute(name, value));
    } else record.addedNodes.forEach(visit);
  }
});
observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: attributes });
observer.observe(document.querySelector('title'), { subtree: true, childList: true, characterData: true });
